// --- this node: job results -> verdict per observable ---------------------
// Reached by exactly one path: no job planned, Cortex unreachable, nothing to
// run after resolving, or the job loop done. Job results come as input items;
// jobs that couldn't run are on the Resolve analyzers items.
const i = $('Called by a workflow').first().json;
const plan = $('Plan').first().json;
const results = $input.all().map((x) => x.json).filter((j) => j.kind === 'cortex_job_result');
if ($('Resolve analyzers').isExecuted) results.push(...($('Resolve analyzers').first().json.unresolved ?? []));
const red = reduceResults(plan, results, i.config.enrichment);
return [{ json: { ...red, jobs: results.length, jobs_from_cache: results.filter((r) => r.from_cache).length,
  cortex_called: $('List Cortex analyzers').isExecuted, warnings: [...plan.warnings, ...red.warnings] } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call is passed on as an error with the number of calls.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.config.thehive_http;
const NODE = 'Fetch alert observables';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// TheHive 5.7.6 returns an alert's observables (with their _id) through the
// query API: getAlert -> observables. Matched on dataType + data.
const r = $input.first().json;
const i = $('Called by a workflow').first().json;
const updates = $('Reduce').first().json.updates;
if (!(r.statusCode >= 200 && r.statusCode < 300) || !Array.isArray(r.body)) {
  const cls = r.statusCode >= 400 && r.statusCode < 500 ? 'thehive_4xx' : 'thehive_error';
  return [{ json: { nothing_to_tag: true, not_tagged: updates.map((u) => ({ key: u.key, class: cls, message: `observable lookup: HTTP ${r.statusCode}` })) } }];
}
const idByKey = new Map(r.body.map((o) => [`${o.dataType}:${o.data}`, o._id]));
const not_tagged = updates.filter((u) => !idByKey.has(u.key))
  .map((u) => ({ key: u.key, class: 'observable_not_found', message: `${u.key} not found on alert ${i.thehive_alert_id}` }));
const toTag = updates.filter((u) => idByKey.has(u.key));
if (toTag.length === 0) return [{ json: { nothing_to_tag: true, not_tagged } }];
return toTag.map((u) => ({ json: { observable_id: idByKey.get(u.key), dataType: u.dataType, data: u.data,
  add_tags: u.add_tags, ioc: u.ioc, thehive_http: i.config.thehive_http, not_tagged } }));

// Reached by exactly one path: nothing to tag, the observable lookup failed
// for good, nothing matched, or the tag loop done.
const red = $('Reduce').first().json;
const inputs = $input.all().map((x) => x.json);
const tagResults = inputs.filter((j) => j.kind === 'tag_result');
const lookupError = inputs.find((j) => j.decision === 'error');
const notTagged = new Map();
if ($('Match observables').isExecuted) for (const n of $('Match observables').first().json.not_tagged ?? []) notTagged.set(n.key, n);
if (lookupError) {
  for (const u of red.updates) notTagged.set(u.key, { key: u.key, class: lookupError.retry_exhausted ? 'thehive_unreachable' : 'thehive_error',
    attempts: lookupError.attempts ?? null, message: lookupError.message ?? null });
}
for (const t of tagResults) {
  if (!t.ok) notTagged.set(`${t.dataType}:${t.data}`, { class: t.class, attempts: t.attempts, message: t.message });
}
const observables = red.observables.map((o) => {
  if (o.status !== 'enriched') return o;
  const n = notTagged.get(`${o.dataType}:${o.data}`);
  return { ...o, tagged: !n, tag_error: n ? { class: n.class, attempts: n.attempts ?? null, message: n.message ?? null } : null };
});
const count = (s) => observables.filter((o) => o.status === s).length;
return [{ json: {
  ok: true,
  counts: { observables: observables.length, enriched: count('enriched'), skipped: count('skipped'), failed: count('failed'),
    jobs: red.jobs, jobs_from_cache: red.jobs_from_cache, tagged: observables.filter((o) => o.tagged === true).length,
    not_tagged: observables.filter((o) => o.tagged === false).length },
  cortex_called: red.cortex_called,
  observables,
  warnings: red.warnings,
} }];
